2	<html lang="zh-CN">
3	
4	<head>
5	  <!-- 适用范围：content-template.html 仅用于内容页(content)；结构页(cover/agenda/section/ending)请勿套用，各自有对应模板，按 style.md「模板使用规则」字面拷贝。配色/字体以 style.md 为唯一权威。 -->
6	  <meta charset="UTF-8">
7	  <meta name="viewport" content="width=1280, height=720">
8	  <title>{{PAGE_TITLE}}</title>
9	
10	  <!-- Tailwind CSS（必选） -->
11	  <script src="https://cdn.digitalhumanai.top/slidagent/pptx-craft/assets/vendors/tailwind.js"></script>
12	  <script src="https://cdn.digitalhumanai.top/slidagent/pptx-craft/assets/vendors/echarts.min.js"></script>
13	
14	  <!-- 字体引用 -->
15	  <link href="https://cdn.digitalhumanai.top/slidagent/pptx-craft/assets/css/fonts.css" rel="stylesheet" />
16	
17	  <!-- Tailwind 配置：工业科技风格配色（以 style.md 为唯一权威） -->
18	  <script>
19	    tailwind.config = {
20	      theme: {
21	        extend: {
22	          colors: {
23	            nvidiaGreen: "#76b900",
24	            gray400: "#898989",
25	          },
26	          fontFamily: {
27	            sans: ["Frex Sans GB", "Noto Sans SC", "sans-serif"],
28	          },
29	        },
30	      },
31	    };
32	  </script>
33	
34	  <!-- 防溢出硬性约束 → 全局 CSS 约束（逐字包含） -->
35	  <style type="text/tailwindcss">
36	    @layer utilities {
37	      /* 幻灯片容器 */
38	      .ppt-slide {
39	        @apply relative w-[1280px] h-[720px] mx-auto box-border overflow-hidden;
40	      }
41	
42	      /* 全局防溢出约束 - 应用到所有子元素 */
43	      .ppt-slide *,
44	      .ppt-slide *::before,
45	      .ppt-slide *::after {
46	        @apply box-border;
47	        max-width: 100%;
48	      }
49	
50	      /* 图片/视频/图表防溢出 */
51	      .ppt-slide img {
52	        @apply max-w-full max-h-full;
53	      }
54	
55	      .ppt-slide video,
56	      .ppt-slide svg,
57	      .ppt-slide .echarts-main,
58	      .ppt-slide .chart-container,
59	      .ppt-slide [id*="chart" i] {
60	        @apply max-w-full max-h-full object-contain;
61	      }
62	
63	      /* 图表容器高度防御 */
64	      .ppt-slide [id*="chart" i],
65	      .ppt-slide .chart-container,
66	      .ppt-slide .echarts-main {
67	        width: 100%;
68	        height: 100%;
69	        min-height: 160px;
70	      }
71	
72	      /* 图表包装器高度防御 */
73	      .ppt-slide :has(> [id*="chart" i]),
74	      .ppt-slide :has(> .chart-container),
75	      .ppt-slide :has(> .echarts-main) {
76	        min-height: 160px;
77	      }
78	
79	      /* 内容安全区：核心内容容器（边距由此统一提供） */
80	      .content-safe {
81	        @apply w-[1220px] h-[660px] my-[30px] mx-auto flex flex-col overflow-hidden;
82	      }
83	
84	      /* 禁止模糊滤镜效果 */
85	      .ppt-slide [class*="blur"],
86	      .ppt-slide [style*="blur"] {
87	        filter: none !important;
88	        backdrop-filter: none !important;
89	      }
90	
91	      /* 禁止半透明渐变背景，使用纯色替代 */
92	      .ppt-slide [class*="gradient"] {
93	        background-image: none !important;
94	      }
95	
96	      /* 禁止毛玻璃效果 */
97	      .ppt-slide [class*="backdrop-blur"],
98	      .ppt-slide [style*="backdrop-filter"] {
99	        backdrop-filter: none !important;
100	      }
101	
102	      /* 全局字体设置：工业科技风格 */
103	      .ppt-slide {
104	        font-family: "Frex Sans GB", "Noto Sans SC", sans-serif !important;
105	      }
106	    }
107	  </style>
108	
109	  <!-- 全局文字颜色 -->
110	  <style>
111	    body {
112	      color: #ffffff;
113	      background: #000000;
114	    }
115	  </style>
116	</head>
117	
118	<body>
119	  <div class="ppt-slide flex flex-col bg-black" type="content">
120	    <div class="content-safe">
121	      <!-- 标题栏（跨页锚点片段：文字样式逐字复用，边距由 content-safe 统一提供） -->
122	      <div class="pt-[40px] pb-[16px] flex-shrink-0">
123	        <h1 class="text-[35px] font-bold text-white leading-[1.25]"
124	          style="font-family: 'Frex Sans GB', 'Noto Sans SC', sans-serif">
125	          {{PAGE_TITLE}}
126	        </h1>
127	        <div class="w-[60px] h-[2px] bg-nvidiaGreen mt-[12px]"></div>
128	      </div>
129	
130	      <!-- 主视觉区：弹性填充 -->
131	      <main class="flex-1 min-h-0 flex flex-col justify-center overflow-hidden">
132	        {{PAGE_CONTENT}}
133	      </main>
134	
135	      <!-- 页脚/注释区（跨页锚点片段：文字样式逐字复用） -->
136	      <div class="pt-[8px] pb-[16px] flex-shrink-0">
137	        <p class="text-[14px] text-gray400" style="font-family: 'Frex Sans GB', 'Noto Sans SC', sans-serif">
138	          {{PAGE_FOOTER}}
139	        </p>
140	      </div>
141	    </div>
142	  </div>
143	    <!-- CHART_SCAFFOLD_BEGIN
144	    <script>
145	      /*
146	       * 图表骨架（图表候选页激活；非图表页保持注释即可，对浏览器与 fix 零副作用）。
147	       * 重要：说明文字必须写在本 script 内的 JS 块注释中，禁止写在 HTML 注释定界符与
148	       * script 之间（否则激活后会成为页面可见裸文本）。
149	       *
150	       * 激活步骤：
151	       *   1) 在 PAGE_CONTENT 放置图表容器，标准写法：
152	       *        div.flex.flex-col > div.flex-1.min-h-0 > div#chart-1.w-full.h-full
153	       *      （容器硬约束：flex flex-col 套 flex-1 min-h-0 套 w-full h-full；可读高度建议 >=300px）
154	       *   2) 成对删除首尾两个定界符：开头的 HTML 注释起始（含 CHART_SCAFFOLD_BEGIN）
155	       *      与结尾的 CHART_SCAFFOLD_END 注释结束，保留中间的 script。
156	       *   3) 把下方 const option = null 的 null 替换为图表 option 对象（series/data/xAxis/yAxis 等）。
157	       *
158	       * 骨架已内置硬约束（机制勿改）：SVG renderer · animation:false 强制 · 全局 textStyle.fontFamily · IIFE · formatter 外部函数。
159	       * CHART_FONT_FAMILY 必须等于当前风格 style.md（custom 为 style-custom.md）frontmatter 的完整字体栈：
160	       *   预设风格模板已预置正确值（勿改）；custom 模板为中性占位值，必须替换后再激活。
161	       * 仍需 designer 自觉遵守（骨架不强制）：
162	       *   - 禁止渐变（colorStops、type 为 linear 或 radial、echarts.graphic.LinearGradient 等会触发导出位图化）；
163	       *     折线/面积图 areaStyle.color 用半透明纯色，如 rgba(<风格主色>, 0.18)，色值以 style.md 为准。
164	       *   - 坐标轴/图例/数据标签的 fontFamily/color 按 style.md 图表色规范设置。
165	       * 设计约束：外层 HTML 注释（BEGIN 与 END 之间）任何位置都不得出现 HTML 注释结束符
166	       * 或连续减号，否则会提前终止外层注释、让非图表页误执行图表代码。
167	       * 多图表：每段独立成 HTML 注释块（CHART_SCAFFOLD_BEGIN 与 CHART_SCAFFOLD_2_BEGIN ），并把第二段标签改为 _2_ 以便区分；切勿把第二段粘贴到第一段注释内部，否则外层注释会在内层第一个 HTML标签注释结束符（减号减号大于号）处提前闭合。改 id（chart-1 改 chart-2）与 getElementById 入参。
168	       */
169	      (function () {
170	        const CHART_FONT_FAMILY = "Frex Sans GB, Noto Sans SC, sans-serif";
171	        // formatter 外部函数模板：
172	        //   axisLabel / xAxis / yAxis 的 formatter 接收原始数值；
173	        //   series.label / tooltip 的 formatter 接收 params 对象（需取 .value）。
174	        // 最多保留小数点后三位，去除末尾多余的零（循环小数如 1/3=0.333... 显示为 0.333）
175	        function trimNumber(v) {
176	          if (v == null || v === "") return "";
177	          var s = Number(v).toFixed(3);
178	          s = s.replace(/(\.\d*?)0+$/, "$1").replace(/\.$/, "");
179	          return s;
180	        }
181	        function formatAxisNumber(v) {
182	          if (v >= 1e8) return (v / 1e8).toFixed(1) + "亿";
183	          if (v >= 1e4) return (v / 1e4).toFixed(1) + "万";
184	          return trimNumber(v);
185	        }
186	        function formatAxisPercent(v) {
187	          return (v * 100).toFixed(1) + "%";
188	        }
189	        function formatLabelNumber(p) {
190	          var v = typeof p === "object" ? p.value : p;
191	          if (v == null) return "";
192	          if (v >= 1e8) return (v / 1e8).toFixed(1) + "亿";
193	          if (v >= 1e4) return (v / 1e4).toFixed(1) + "万";
194	          return trimNumber(v);
195	        }
196	        function formatLabelPercent(p) {
197	          var v = typeof p === "object" ? p.value : p;
198	          if (v == null) return "";
199	          return (v * 100).toFixed(1) + "%";
200	        }
201	        const el = document.getElementById("chart-1");
202	        if (!el) return;
203	        // 激活后把下方 null 替换为图表 option 对象，例如：
204	        //   { xAxis:{type:"category",data:[...]}, yAxis:{type:"value"}, series:[{data:[...],type:"bar"}] }
205	        // 注意：option 校验必须在 echarts.init 之前，否则未替换 null 时仍会创建实例并产出空 SVG，
206	        // 进而被 convert 阶段渲染为空图（fix 已不再落盘 ECharts，由 convert 阶段现场渲染）。
207	        const option = null;
208	        if (!option) return; // 未填 option 则跳过，避免执行 echarts.init 产出空图
209	        const chart = echarts.init(el, null, { renderer: "svg" });
210	        option.animation = false; // 强制禁动画，PPT 静态输出必须禁用，不可覆盖
211	        option.textStyle = Object.assign({ fontFamily: CHART_FONT_FAMILY }, option.textStyle);
212	        chart.setOption(option);
213	      })();
214	    </script>
215	    CHART_SCAFFOLD_END -->
216	</body>
217	
218	</html>
