    @layer utilities {
      /* 幻灯片容器 */
      .ppt-slide {
        @apply relative w-[1280px] h-[720px] mx-auto box-border overflow-hidden;
      }

      /* 全局防溢出约束 - 应用到所有子元素 */
      .ppt-slide *,
      .ppt-slide *::before,
      .ppt-slide *::after {
        @apply box-border;
        max-width: 100%;
