      .ppt-slide [id*="chart" i],
      .ppt-slide .chart-container,
      .ppt-slide .echarts-main {
        width: 100%;
        height: 100%;
        min-height: 160px;
      }

      /* 图表包装器高度防御 */
      .ppt-slide :has(> [id*="chart" i]),
      .ppt-slide :has(> .chart-container),
